/**
 * gungtong_jomun.js — 궁통보감 조건절 조문 (열 일간 120칸)
 * 사주팔자집 · 2026-09-05 (2026-10-07 전수 점검: 공유칸 해체·머리 글자 집합을 gungtong.js와 통일·조건 모순 조문 9건·판정어 날조 7건 고침)
 *
 * gungtong.js는 재고조사다 — 「이 달에 필요한 글자가 무엇이고 원국에 있는가」까지.
 * 이 모듈은 그 다음, 원문이 실제로 하는 말을 한다 — 「그래서 이 배합은 이렇다」.
 *
 *   正月己土 … 忌見壬水 … 壬多要見戊制。有戊出干者，定主玉堂金馬。若乏戊制，必屬平常。
 *   → 조문 ① 壬多·戊透  → 玉堂金馬   ② 壬多·戊無 → 平常
 *
 * ── 원칙 ────────────────────────────────────────────────
 * 1. 조건은 원문의 글자(丙·壬·戊…)로 쓴다. 궁통보감은 십성이 아니라 글자로 말한다.
 * 2. 판정어는 **원문 그대로 보이고**, 그 옆에 **결 번역**을 단다(사용자 결정 2026-09-05).
 *    결 번역은 배합의 상태를 말하지 사람을 평가하지 않는다 — 「奸詐小人」은 「乙이 여럿이면
 *    밭을 갈기는커녕 어지럽히는 배합」이지 「이 사람은 간사하다」가 아니다(21편 품행 평가 금지).
 * 3. 질병·수명·자녀 수 언급(目疾·夭·刑剋)은 원문 인용에 남되 결 번역에서는 옮기지 않는다.
 * 4. 妻子 배속(木妻火子)은 조문화하지 않는다 — 앱 원칙(육친은 23편 두 축)과 겹친다.
 * 5. 한 칸에서 여러 조문이 걸리면 전부 보여준다. 원문 순서가 곧 우선순위다.
 *    (예외: 특수 맥락 조문이 일반 조문에 가려지는 쌍은 특수 쪽을 앞에 둔다 — 庚亥·戊冬·庚辰·庚子, 2026-10-07.
 *     같은 날 도달성 조사(scripts/gungtong_reach.js: 현실 전수 17,280/칸 + 무제약 표본)로 「걸리되 주판정이 된 적 없는」
 *     판정 조문 52개를 찾아 그 가운데 더 좁은 조건이 뒤에 있던 49개를 앞으로 옮겼다 — 옮긴 자리마다 주석. 남은 것은
 *     甲冬-02(판정어 없는 공유 조문, 子·丑월 전용 조문이 앞서는 게 맞다)뿐.)
 * 6. 머리(용·기)는 **gungtong.js 표(원전 취용 문장)와 글자 집합이 같아야 한다** — verify_gungtong.js가 120칸을 검사한다.
 *    공유칸(申酉戌·亥子丑·午未 한 객체)은 2026-10-07에 해체했다: 조문 배열만 같이 쓰고 머리는 달마다 둔다.
 *    기(忌)에는 글자(또는 글자+多)만 적는다 — '水局' 같은 조건은 요지로. 기에 든 글자가 용에도 들면 안 된다.
 * 7. 원문에 판정어가 없는 조문은 판정 칸에 '(원문 판정어 없음)' 을 적는다. 방향(으뜸~막힘)이 null이 되어
 *    결말 문장이 붙지 않고, 화면·브리프에는 「(원문 판정어 없음)」 으로 보인다. 판정어를 지어 넣지 않는다.
 *
 * ── 남긴 과제 (2026-10-07 점검, 코드로는 아직 바꾸지 않음 — 사람 결정) ─────────
 * ㄱ. (2026-10-07 조문 층 검증에서 처리) 有/無 ↔ 藏 비대칭 — 藏을 중기·정기로 좁혔고(여기는 어디에도 안 센다), 같은 칸에
 *    「X藏」 조문이 있는 「無X」 조문 40개에는 無藏(無 && !藏)을 써서 두 조문이 함께 걸리지 않게 했다(원시 연산 주석 참조).
 *    無 자체는 !有 그대로다 — 원문이 寅월 「無丙」·金局 「無火」처럼 중기를 안 세는 자리가 많아서다. gungtong.js 어디()는 여전히 지장간 전부를 「지지에 숨음」으로
 *    세므로 두 모듈이 같은 글자를 다르게 답할 수 있다 — 브리프에 「조문의 有/無는 중기·정기 기준」 한 줄을 명시할 것.
 *    得地·有根은 여기까지 포함(지장간 전부)인 채 두었다. 己卯-05/-06 「庚制甲」의 卯 속 甲(여기)은 원래 주석대로 raw 지장을 본다.
 * ㄴ. (2026-10-07 두 번째 통합에서 처리) 合去의 일간 처리 — 합거일간포함(c,g) 를 두어 己卯-01/-02/-03 「忌合」이 일간 己와의 합을 센다
 *    (월간·시간 甲은 일간과 늘 이웃이라 이제 년간 甲만 忌合을 피한다 — 원문 「先取甲木疏之，忌合」 글자 그대로). 丁寅-04·丁秋-06·癸辰-02 처럼
 *    「다른 천간에 뺏기지 않음」 뜻의 合去===false 는 옛 정의 그대로. 丙寅-06 辛年辛時·辛辰-05 月時皆丙 爭合은 年/時·透수 조건이 이미 일간 합을 뜻하므로 안 바꿈.
 *    格리(隔位)는 미구현(傷 참조).
 *
 * ── 2026-10-07 두 번째 통합 (gungtong.js·gungtong_jomun.js·verify·reach) ─────────
 * ① 머리 단일 출처 — 용·보좌·기·요지(두 벌)·원문은 gungtong.js 표 한 곳. 이 파일의 칸 객체는 조문만 가지고, 적재 때 G.칸()으로 머리를 채운다.
 *    소재 정의 통일: 藏=중기·정기, 無=천간·중기·정기 모두 없음(조문의 無는 정기까지만 — 머리 ㄱ 그대로), 월령 표시. gungtong.어디()도 여기를 안 센다(verify ② 25/25 유지).
 * ② 용신 손상(gungtong.analyze 용신상태) — 극(같은 음양)·합거(일간 합은 opt.합거일간포함)·설기. 한계 명례 癸丑辛酉庚子丁亥 가 「손상」으로 읽힌다.
 * ③ 有根/無根/虛浮 — 有根 = 통근(tonggeun, 같은 오행 뿌리), 透有根·透無根. 원문이 透+根을 말하는 조문(庚寅-07/08·乙午-01·己秋-05·丙寅-13·丙卯-01·甲冬-04·己夏-05)에 썼다. 得地(같은 글자)는 그대로.
 * ④ 반월·時·隨宜酌用 — 上半月/下半月 연산(乙酉-16/17 새 조문), 時/時支 는 시주 없으면 보류(analyze 결과 `보류`), gungtong.analyze 의 용순서·용역할·용선택사유(乙午·乙酉·壬丑·癸辰·癸未·丙亥, 참작 글자).
 * ⑤ 갖춤 = 온전·암장·손상·없음(+갖춤설명), 옛 네 단계는 갖춤구.
 * ⑥ 富·貴 두 축 `축:{부,귀}`(+·0·-·null)·축풀이 — 壽·夭·질병·刑剋은 null. 방향은 그대로.
 * ⑦ 특수성 정렬 — 조건 함수의 원시 연산 수(목록 꼴 1, 支全/干全 인자 수, 수 비교 +1)로 칸 안 내림차순, 같으면 원문 순. 세기가 원문의 넓이를 못 잡는 곳은 `특수성(J(...), n)` 으로 손 조정
 *    (甲冬-02 0·戊春-03 2·庚巳-02 1·辛酉-05 3·壬辰-03 2) 하고, 원문이 따로 다루는 좁은 경우를 넓은 조문에서 뺐다(丁卯-05·戊春-02·庚寅-02). reach: 주판정 0 조문 1(그대로), 명례 29 그대로.
 * ⑧ 층 — 모든 조문에 층 '원전', 평주 조문 P(...) 셋(庚寅-P1·庚卯-P1·庚巳-P1)은 `평주판정` 으로만 나가고 주판정은 늘 원전.
 * ⑨ 여명 조문 7건(유형 '여명', opt.성별==='여' 일 때만, 결과 `여명`) — 품행·흉단 판정어는 표시금지. scripts/gungtong_women_check.js.
 *
 * ── 2026-10-07 8차(궁통보감 남은 것, docs/PROMPTS.md 3) — 두 번째 통합 뒤 남긴 과제 ㄷ~ㅇ 처리 ─────────
 * ㄷ. 壬戌-01/-02: 원문 낱말대로 -01 一派壬水(多오행 水 또는 水局, 일간 壬 포함 넷)·-02/-03 一派戊土(一派 ≥4)로 고쳐 두 배합이 겹치지 않는다(자리 주석). 癸丑-05 는 「即有丙透」 예외절이라 특수성 4 로 -02 앞.
 * ㄹ. 설기 = 설점수(낳는 오행 천간 수 + 통근 점수) ≥ 2.5 — gungtong.js 머리에 근거. 극은 같은 음양(인접·격위) + 음간→양간(인접만, 원문 「丁破庚」「癸制丙」「乙破戊」).
 * ㅁ. 반월 = 중기(中氣) 기준 — gungtong.반월of 가 m.반월 → m.jd/m.생시(중기 계산) → daysFromJeolip 15일 폴백 차례. interpret·manse 는 안 건드렸으므로 화면·서버 경로는 아직 15일 폴백이다(남긴 것 — m.생시 를 넘기는 한 줄은 interpret 몫).
 * ㅂ. (그대로) reach 현실 전수는 시지 홀짝으로 5/20일을 넣는다.
 * ㅅ. 1523행 「女命」 명례 癸未庚戌己丑庚辰 — verify ⑥ fixture(성별 여, 주판정 없음·여명 조문 없음·갖춤 없음 기록).
 * ㅇ. 질병 조문 — 아래 `질병조문` 11건(표시금지, 유형 '질병') + 칸 조문에 질병·수명 낱말이 든 것은 적재 때 표시금지 플래그. scripts/gungtong_women_check.js 가 검사.
 *
 * ── 원문 출처 ────────────────────────────────────────────
 *   여춘태본 窮通寶鑑 「己土」 四季 전문 — ncc.com.tw/fate/paleo/bg/bg_11.htm (2026-09-05 채록),
 *   위키문헌·udn 판본과 자구 대조.
 */

const { JIJANGGAN } = require('./jijanggan');
const G = require('./gungtong');            // 120칸 머리(용·보좌·기·요지)의 단일 출처 — 이 모듈은 조문만 가진다(2026-10-07)
const { tonggeun } = require('./tonggeun');  // 有根/無根

const 오행 = { 甲:'木',乙:'木',丙:'火',丁:'火',戊:'土',己:'土',庚:'金',辛:'金',壬:'水',癸:'水' };
const 삼합 = { 木:['亥','卯','未'], 火:['寅','午','戌'], 金:['巳','酉','丑'], 水:['申','子','辰'] };
const 방합 = { 木:['寅','卯','辰'], 火:['巳','午','未'], 金:['申','酉','戌'], 水:['亥','子','丑'] };
const 간합 = { 甲:'己',己:'甲',乙:'庚',庚:'乙',丙:'辛',辛:'丙',丁:'壬',壬:'丁',戊:'癸',癸:'戊' };
const 사고 = ['辰','戌','丑','未'];

// ── 보류(판정 불가) — 時 조건인데 시주가 없을 때 ───────────────
//   조건 함수 안에서 時/時支 를 평가하는 순간 시주가 없으면 이 오류를 던지고, analyze 가 받아 `보류:[{id,사유}]` 에 넣는다.
//   JS 단락 평가라 時 까지 가지 않는 조건은 보류되지 않는다(2026-10-07).
class 보류오류 extends Error { constructor(사유) { super(사유); this.보류 = 사유; } }

// ── 원시 연산 — 원문 어휘를 그대로 함수 이름으로 ─────────────
function ctx만들기(m, opt = {}) {
  const 천간 = [m.yeonGan, m.wolGan, m.siGan].filter(Boolean);        // 일간 제외
  const 지지 = [m.yeonJi, m.wolJi, m.ilJi, m.siJi].filter(Boolean);
  const 지장 = [];                                                    // 지지 속 글자 전부
  for (const j of 지지) for (const h of (JIJANGGAN[j] || [])) 지장.push(h.gan);
  const 정기 = 지지.map(j => { const h = (JIJANGGAN[j] || []).find(x => x.wi === '정기'); return h ? h.gan : null; }).filter(Boolean);
  const 중정기 = [];                                                  // 지지 속 글자 가운데 여기(餘氣)를 뺀 것 — 藏의 기준
  for (const j of 지지) for (const h of (JIJANGGAN[j] || [])) if (h.wi !== '여기') 중정기.push(h.gan);
  const 타지중기 = [];                                                // 월지를 뺀 년·일·시지의 중기 — 無藏의 기준(월지 중기는 그 달에 늘 있으니 「無」를 막지 않는다)
  for (const j of [m.yeonJi, m.ilJi, m.siJi]) for (const h of (JIJANGGAN[j] || [])) if (h.wi === '중기') 타지중기.push(h.gan);
  const 성별 = opt.성별 || opt.gender || null;
  return { m, 일간: m.ilGan, 천간, 지지, 지장, 정기, 중정기, 타지중기, 월지: m.wolJi,
    반월: G.반월of(m), 시주없음: !m.siGan, 성별 };
}
// 有/無의 기준 — 궁통보감이 「有戊」「無癸」라 할 때 지장간 여기(餘氣)까지 세면 조문이 죽는다.
//   寅월은 寅 속에 戊가 늘 있어 「乏戊制」가 영원히 거짓이 되고, 卯월은 卯 속 甲 때문에 「無甲」이
//   거짓이 된다(2026-09-05 전수 점검에서 10조문 미발동으로 드러남). 원문의 有/無는 천간에 드러남과
//   지지 본기(정기)를 세는 것으로 읽는다 — 자평진전 격 취용의 정기 우선과 같은 기준.
//   藏은 천간에는 없되 지지 속 중기·정기에 있는 것. 여기(餘氣 — 寅戊·卯甲·辰乙·巳戊·午丙·未丁·申戊·酉庚·戌辛·亥戊·子壬·丑癸)는
//   藏으로 세지 않는다(2026-10-07 도달성 조사): 여기까지 세면 卯월은 「甲藏」, 申·亥월은 「戊藏」이 언제나 참이 되어
//   丁卯-02 「庚透甲藏」이 「庚透乙藏」(-05)과 구별되지 않고, 丙申-02 「戊藏支內」·壬亥-03 「戊藏無制」가 그 달의 모든 명식에
//   걸렸다. 평주 명례가 藏이라 부르는 자리는 모두 중기·정기(申宮壬水·亥宮藏甲·寅中丙火·午中丁火)다.
//   無는 !有(천간에도 정기에도 없음) 그대로 둔다 — 중기에만 있는 글자는 藏이면서 無다. 원문 자체가 그렇게 쓴다:
//   甲寅 「如無丙癸，平常」(寅 속 丙은 늘 있다), 庚丑 「支成金局無火」(申酉戌의 戌 속 丁은 불로 안 센다). 다만 같은 칸에
//   「X藏→…」 조문이 따로 있으면 그 칸의 「無X」는 (월지 밖의) 藏도 아닌 것이다 — 그런 칸의 無X 전부(같이 걸리던 쌍 42개,
//   戊冬-03/-05 ×6,514 등, 도달성 조사)에 無藏을 썼다(2026-10-07). 無를 통째로 「중기까지 없음」으로 바꿔 보니 조문 43개가 영원히 안 걸렸다.
const 透   = (c, g) => c.천간.includes(g);                             // 천간에 드러남
const 支中 = (c, g) => c.중정기.includes(g);                            // 지지 속 중기·정기에 있음(천간 여부 무관)
const 藏   = (c, g) => !透(c, g) && 支中(c, g);                         // 지지 속에만(중기·정기)
const 有   = (c, g) => 透(c, g) || c.정기.includes(g);                  // 드러남 또는 본기
const 無   = (c, g) => !有(c, g);                                      // 천간에도 정기에도 없음(중기는 안 봄)
const 無藏 = (c, g) => 無(c, g) && !c.타지중기.includes(g);              // 같은 칸에 「X藏」 조문이 있는 「無X」 — 년·일·시지의 중기에도 없어야 한다.
//   월지 자신의 중기(辰癸·寅丙·亥甲·申壬·戌丁·丑辛·未乙·巳庚)는 세지 않는다 — 그 달엔 늘 있으므로 원문의 「無」가 그것까지
//   없다는 뜻일 수 없다(戊辰 「丙多無癸」·「不見丙甲癸」, 戊亥 「丙甲俱無」, 癸寅 「辛丙皆無」가 그 달에서 영원히 안 걸렸다).
const 透수 = (c, g) => c.천간.filter(x => x === g).length;
const 多   = (c, g) => 透수(c, g) >= 2 || (透수(c, g) >= 1 && c.정기.includes(g));   // 둘 이상 드러남, 또는 드러남+정기
const 오행透수 = (c, o) => c.천간.filter(g => 오행[g] === o).length;
const 一派 = (c, o) => (오행透수(c, o) + c.정기.filter(g => 오행[g] === o).length) >= 4;   // 천간+정기 합쳐 넷 이상
const 支四庫 = c => 사고.filter(j => c.지지.includes(j)).length >= 3;
const 支成局 = (c, o) => o === '土' ? 支四庫(c) : (삼합[o].every(j => c.지지.includes(j)) || 방합[o].every(j => c.지지.includes(j)));   // 土局은 사고(辰戌丑未) 셋 이상
const 得地 = (c, g) => c.정기.includes(g) || c.지장.includes(g);        // 지지에 자리(같은 글자가 지장간 어디든) — 得所·得地 조문용
// 有根/無根(2026-10-07): 통근 — 같은 오행의 뿌리가 지지(지장간 전부, tonggeun.js 가중)에 있는가. 원문 「壬透有根」「癸水無根」「虛浮」 조문이 쓴다.
//   得地(같은 글자)와 다르다: 壬은 子(癸)·丑(癸)에도 뿌리가 있다. 뿌리 점수가 0보다 크면 有根.
const 有根 = (c, g) => tonggeun(g, [['년', c.m.yeonJi], ['월', c.m.wolJi], ['일', c.m.ilJi], ['시', c.m.siJi]]).score > 0;
const 透有根 = (c, g) => 透(c, g) && 有根(c, g);                        // 드러나고 뿌리 있음
const 透無根 = (c, g) => 透(c, g) && !有根(c, g);                       // 드러났으나 뿌리 없음 = 虛浮
const 合去 = (c, g) => {                                              // g가 곁 천간과 합해 묶임(일간 낀 합은 제외)
  const 차례 = [m => m.yeonGan, m => m.wolGan, m => m.ilGan, m => m.siGan].map(f => f(c.m));
  for (let i = 0; i < 4; i++) if (차례[i] === g) {
    for (const j of [i - 1, i + 1]) if (j >= 0 && j < 4 && j !== 2 && 차례[j] === 간합[g]) return true;
  }
  return false;
};
// 합거일간포함(2026-10-07, 머리 ㄴ 처리): g(년·월·시간)가 곁 자리와 합하되 **일간과의 합도 센다**. 己卯 「忌合」(甲의 합 상대는 보통 일간 己),
//   丙寅 「辛年辛時 貪合」, 辛辰 「月時皆丙 爭合」 처럼 일간이 합의 본체인 조문용. 일간 자리 자체는 주체가 되지 않는다.
const 합거일간포함 = (c, g) => {
  const 차례 = [c.m.yeonGan, c.m.wolGan, c.m.ilGan, c.m.siGan];
  for (const i of [0, 1, 3]) if (차례[i] === g) {
    for (const j of [i - 1, i + 1]) if (j >= 0 && j < 4 && 차례[j] === 간합[g]) return true;
  }
  return false;
};
const 比劫重重 = c => (오행透수(c, '土') + c.정기.filter(g => 오행[g] === '土').length) >= 2;   // 천간 세 자리로는 못 채우니 본기까지
const 無比印 = c => 오행透수(c, '土') === 0 && 오행透수(c, '火') === 0 && !c.정기.some(g => 오행[g] === '土' || 오행[g] === '火');
const 일간무근 = c => !c.중정기.some(g => 오행[g] === '土');          // 뿌리 = 중기·정기(여기는 안 셈 — 有/無·藏과 같은 기준, 2026-10-07)
const 官殺滿 = c => (오행透수(c, '木') + c.정기.filter(g => 오행[g] === '木').length) >= 3;
const 財滿 = c => (오행透수(c, '水') + c.정기.filter(g => 오행[g] === '水').length) >= 3;
const 傷 = (c, 극하는, 극당하는) => 透(c, 극하는) && 透(c, 극당하는);  // 둘 다 천간에 드러나 부딪힘(격리는 미구현)
const 有오행 = (c, o) => c.천간.some(g => 오행[g] === o) || c.정기.some(g => 오행[g] === o);
const 無오행 = (c, o) => !有오행(c, o);
const 透오행 = (c, o) => c.천간.some(g => 오행[g] === o);
const 支多 = (c, o) => c.정기.filter(g => 오행[g] === o).length >= 2;        // 지지 본기 둘 이상
const 多오행 = (c, o) => (오행透수(c, o) + c.정기.filter(g => 오행[g] === o).length) >= 3;
const 支見 = (c, ...js) => js.some(j => c.지지.includes(j));
const 支全 = (c, ...js) => js.every(j => c.지지.includes(j));
const 干全 = (c, ...gs) => gs.every(g => 透(c, g));
const 干皆 = (c, o) => c.천간.length >= 2 && c.천간.every(g => 오행[g] === o);   // 천간 전부 한 오행
const 比劫 = c => 오행透수(c, 오행[c.일간]);
const 무비겁 = c => 比劫(c) === 0 && !c.정기.some(g => 오행[g] === 오행[c.일간]);
const 無水 = c => 無오행(c, '水'), 無火 = c => 無오행(c, '火'), 無金 = c => 無오행(c, '金'), 無木 = c => 無오행(c, '木'), 無土 = c => 無오행(c, '土');
const 有水 = c => 有오행(c, '水'), 有火 = c => 有오행(c, '火'), 有金 = c => 有오행(c, '金'), 有木 = c => 有오행(c, '木'), 有土 = c => 有오행(c, '土');
// 時 조건 — 시주가 없으면 판정하지 않고 보류한다(2026-10-07)
const 時 = (c, g) => { if (c.시주없음) throw new 보류오류('시간 미상'); return c.m.siGan === g; };
const 時支 = (c, j) => { if (c.시주없음) throw new 보류오류('시간 미상'); return c.m.siJi === j; };
const 年 = (c, g) => c.m.yeonGan === g, 月干 = (c, g) => c.m.wolGan === g;
// 반월 — 절입 경과일 15일 미만이 上半月. 경과일이 없으면 보류(2026-10-07). 白露/秋分·清明/穀雨도 15일 간격이라 같은 기준
const 上半月 = c => { if (!c.반월) throw new 보류오류('절입 경과일 없음'); return c.반월 === '상'; };
const 下半月 = c => { if (!c.반월) throw new 보류오류('절입 경과일 없음'); return c.반월 === '하'; };
/** 조문 한 줄 만들기 */
const J = (id, 종류, 조건, 원문, 판정, 결, 월) => 월 ? { id, 종류, 조건, 원문, 판정, 결, 월 } : { id, 종류, 조건, 원문, 판정, 결 };
/** 평주 조문 — 서락오 평주 명례가 원전 조문보다 높게 읽는 배합. 주판정은 늘 원전이고, 이것은 `평주판정` 으로 따로 나간다(2026-10-07) */
const P = (id, 조건, 근거, 판정, 결, 방향) => ({ id, 종류: '판정', 층: '평주', 조건, 원문: 근거, 판정, 결, 방향 });
/** 특수성을 손으로 정함 — 조건 수 세기가 원문의 넓고 좁음을 못 잡는 조문(「透一二」「二藏一透」 같은 목록 꼴, 판정어 없는 공유 조문). 이유는 그 자리 주석에 */
const 특수성 = (j, n) => Object.assign(j, { 특수성: n });

