    // 8차(2026-10-07) 癸丑-02 ↔ -05 재판단(2150행): -05 「或支見子丑，比肩出干，**即有丙透**，不能解凍，此屬平常」 는 丙透 조문(-01·-02·-03)에 대한 예외절이다 —
