// ── 원문 그대로 보기 (10차, 2026-10-07 — 사용자 지시 「원전에 나와 있으면 흉단 질병 신살도 구현해」) ─────────────────
//   analyze 의 출력은 그대로 가린다(브리프·Gemini·문답·간명서 본문 어디에도 안 나간다). 이 함수만이 표시금지 조문의 원문을 돌려주며,
//   화면의 「원문 그대로 보기」(전문가용, 기본 꺼짐, 브라우저 안에서만) 가 부른다. 서버로 가지 않고 Gemini 재료에도 들어가지 않는다.
//   신살은 넣지 않는다 — 자평진전 21편 「論星辰無關格局」이 격국과 무관하다 하였고 궁통보감도 조문으로 쓰지 않는다.
const 원문보기안내 = '옛 문헌의 표현을 글자 그대로 옮긴 것입니다. 배합에 대한 기록이지 사람의 몸·수명·됨됨이에 대한 진단이나 예측이 아니며, 몸의 일은 의료 전문가에게 물으셔야 합니다.';
function 원문보기(m, opt = {}) {
  const R = 걸린조문(m, opt);
  if (!R) return { 해당없음: true, 항목: [], 안내: 원문보기안내 };
  const 항목 = [];
  const 자리of = j => j.종류 === '판정' ? (R.주 && R.주.id === j.id ? '주판정' : j.층 === '평주' ? '평주' : '함께 걸린 조건') : j.종류;
  for (const j of R.걸린) if (j.표시금지) 항목.push({ id: j.id, 유형: j.유형, 자리: 자리of(j), 원문: j.원문, 판정어: j.판정 || null, 결: j.결, 줄: j.줄 ?? null });
  for (const j of R.여명) 항목.push({ id: j.id, 유형: '여명', 자리: '여명 조문', 원문: j.근거 || j.원문, 판정어: null, 결: j.결, 줄: j.줄 ?? null, 표시금지: !!j.표시금지 });
  for (const j of R.질병) 항목.push({ id: j.id, 유형: '질병', 자리: '질병 기록', 원문: j.근거, 판정어: null, 결: j.결, 줄: j.줄 ?? null, 표시금지: true });
  return { 해당없음: false, 일간: m.ilGan, 월: m.wolJi, 항목, 안내: 원문보기안내 };
}

/** 걸린 조문 계산 — analyze 와 scripts/gungtong_reach.js 가 같이 쓴다 */
function 걸린조문(m, opt = {}) {
  const 일 = m.ilGan, 월 = m.wolJi;
  if (!표[일] || !표[일][월]) return null;
  const c = ctx만들기(m, opt);
  const 걸린 = [], 보류 = [];
  for (const j of 정렬조문(일, 월)) {
    let ok = false;
    try { ok = !!j.조건(c); } catch (e) { if (e && e.보류) 보류.push({ id: j.id, 사유: e.보류 }); }
    if (ok) 걸린.push(j);
  }
  const 여명 = [];
  if (c.성별 === '여') for (const j of 여명조문) {
    const 일간맞음 = Array.isArray(j.일간) ? j.일간.includes(일) : j.일간 === 일;
    if (!일간맞음 || (j.월 && !j.월.includes(월))) continue;
    let ok = false;
    try { ok = !!j.조건(c); } catch (e) { if (e && e.보류) 보류.push({ id: j.id, 사유: e.보류 }); }
    if (ok) 여명.push(j);
  }
  const 질병 = [];
  for (const j of 질병조문) {
    if (j.일간 !== 일 || (j.월 && !j.월.includes(월))) continue;
    let ok = false;
    try { ok = !!j.조건(c); } catch (e) { if (e && e.보류) 보류.push({ id: j.id, 사유: e.보류 }); }
    if (ok) 질병.push(j);
  }
  const 판정들 = 걸린.filter(j => j.종류 === '판정' && j.층 !== '평주');
  const 평주들 = 걸린.filter(j => j.층 === '평주');
  return { c, 걸린, 보류, 여명, 질병, 판정들, 주: 판정들[0] || null, 평주: 평주들[0] || null };
}

// 판정꼴 — 방향·축은 원문 판정어로 읽고, 보이는 원문·판정어는 표시금지면 가린다(8차)
const 판정꼴 = j => { const 방향 = j.방향 || 방향찾기(j.판정); const 축 = 축찾기(j.판정); const 공 = 공개꼴(j); return { id: j.id, 층: j.층 || '원전', 원문: 공.원문, 판정어: 공.판정, 방향, 축, 축풀이: 축풀이(축), 결: j.결, 특수성: j.특수성, ...(공.표시금지 ? { 표시금지: true, 유형: 공.유형 } : {}) }; };
const 보조꼴 = j => { const 공 = 공개꼴(j); return { id: j.id, 원문: 공.원문, 결: j.결, ...(공.표시금지 ? { 표시금지: true, 유형: 공.유형 } : {}) }; };

/**
 * @param {object} m 명식 {yeonGan..siJi, daysFromJeolip?}
 * @param {object} opt { 성별|gender: '남'|'여', 합거일간포함 }
 * @returns 조문 판정 (없는 일간·달이면 {해당없음:true})
 */
function analyze(m, opt = {}) {
  const 일 = m.ilGan, 월 = m.wolJi;
  const R = 걸린조문(m, opt);
  if (!R) return { 해당없음: true, 사유: `${일}일간 ${월}월은 아직 조문화되지 않음` };
  const 칸 = 표[일][월];
  const { 걸린, 보류, 여명, 질병, 판정들, 주, 평주 } = R;
  const 방향 = 주 ? 방향찾기(주.판정) : null;
  const 주꼴 = 주 ? 판정꼴(주) : null;
  const 평주꼴 = 평주 ? 판정꼴(평주) : null;
  return {
    해당없음: false, 일간: 일, 월: 월,
    용: 칸.용, 보좌: 칸.보좌, 기: 칸.기, 요지: 칸.요지,
    // 결말은 늘 문자열 — haeseol.js가 마침(결말)을 그대로 부르므로 null이면 간명서의 궁통 단락이 통째로 빠진다 (2026-10-07)
    주판정: 주 ? { ...주꼴, 결말: 방향 ? 결말[방향] : '원문에 판정어가 없는 조건이라 결 번역으로만 읽습니다' } : null,
    // 평주판정 — 서락오 평주 명례가 원전 조문보다 높게 읽는 배합(庚寅·庚卯·庚巳). 주판정(원전)과 다를 때만 채운다
    평주판정: 평주꼴 && (!주꼴 || 주꼴.id !== 평주꼴.id) ? { ...평주꼴, 결말: 평주꼴.방향 ? 결말[평주꼴.방향] : '', 갈림: !주꼴 || 주꼴.방향 !== 평주꼴.방향 } : null,
    바탕: 걸린.filter(j => j.종류 === '바탕').map(보조꼴),
    흠:   걸린.filter(j => j.종류 === '흠').map(보조꼴),
    완화: 걸린.filter(j => j.종류 === '완화').map(보조꼴),
    그밖의판정: 판정들.slice(1).map(판정꼴),
    여명: 여명.map(여명표시),
    질병: 질병.map(질병표시),   // 배합만 기록 — 브리프줄·haeseol 에 내지 않는다(8차)
    보류,
    반월: R.c.반월,
    걸린수: 걸린.length,
    조문수: 칸.조문.filter(j => !j.월 || j.월 === 월).length,
  };
}

/** 브리프용 줄 — haeseol.toLLMBrief에서 부른다 */
function 브리프줄(r) {
  if (!r || r.해당없음) return [];
  const L = [];
  L.push(`[궁통보감 조건절 — ${r.일간}일간 ${r.월}월] 이 달의 필요 글자 ${r.용.join('→')}${r.기.length ? `, 꺼리는 글자 ${r.기.join('·')}` : ''}. ${r.요지}`);
  const 축줄 = x => { const p = []; if (x.축풀이?.부) p.push(`살림 ${x.축.부}`); if (x.축풀이?.귀) p.push(`자리 ${x.축.귀}`); return p.length ? ` [두 축: ${p.join(' · ')}]` : ''; };
  if (r.주판정 && r.주판정.표시금지) L.push(`  판정: (원문 인용 비공개 — 정책) — ${r.주판정.결}.${r.주판정.결말 ? ' (' + r.주판정.결말 + ')' : ''} **이 자리의 원문·판정어는 표시하지 않으며 그 내용을 추측해 쓰지 말 것**`);
  else if (r.주판정 && /^\(원문 판정어 없음\)/.test(r.주판정.판정어)) L.push(`  판정: 「${r.주판정.원문}」 — 이 조건에는 원문 판정어가 없다. 판정어를 지어 쓰지 말고 결 번역으로만 말할 것 — ${r.주판정.결}.`);
  else if (r.주판정) L.push(`  판정: 「${r.주판정.원문}」 → 원문 판정어 「${r.주판정.판정어}」 — ${r.주판정.결}.${r.주판정.결말 ? ' (' + r.주판정.결말 + ')' : ''}${축줄(r.주판정)}`);
  else L.push('  판정: 이 명식은 원문이 든 조건절 어디에도 정확히 들어맞지 않는다. 바탕과 흠으로만 말할 것');
  if (r.평주판정) L.push(`  평주(서락오) 읽기: 「${r.평주판정.원문}」 — ${r.평주판정.결}. 원전 조문과 ${r.평주판정.갈림 ? '갈린다 — 「원전은 이렇게, 평주의 명례는 이렇게」로 나누어 말할 것' : '방향은 같다'}`);
  const 인용 = x => x.표시금지 ? '(원문 인용 비공개 — 정책)' : `「${x.원문}」`;
  r.바탕.forEach(x => L.push(`  바탕: ${인용(x)} — ${x.결}`));
  r.흠.forEach(x => L.push(`  흠: ${인용(x)} — ${x.결}`));
  r.완화.forEach(x => L.push(`  완화: ${인용(x)} — ${x.결}`));
  r.그밖의판정.forEach(x => L.push(x.표시금지 ? `  함께 걸린 조건: (원문 인용 비공개 — 정책) — ${x.결}` : `  함께 걸린 조건: 「${x.원문}」 → 「${x.판정어}」 — ${x.결}`));
  (r.여명 || []).forEach(x => L.push(`  여명 조문: ${x.표시금지 ? '(원문 인용 비공개 — 정책)' : '「' + x.원문 + '」'} — ${x.결}. **원문의 그 자리 판정어는 절대 옮기지 말 것**`));
  if (r.보류 && r.보류.length) L.push(`  보류(판정 못 함): ${r.보류.map(x => `${x.id}(${x.사유})`).join(', ')} — 시주·절입일이 없어 이 조문은 걸리는지 알 수 없다. 걸린 것처럼도, 안 걸린 것처럼도 말하지 말 것`);
  L.push('  **원문 판정어(科甲·平常·孤苦 등)는 배합에 대한 옛 표현이지 사람에 대한 등급이 아니다.** 답에 옮길 때는 반드시 결 번역으로 말하고, 원문 판정어는 인용으로만 보인다. 품행어(奸詐·狡詐)는 배합 설명에만 쓰고 사람 됨됨이로 옮기지 않는다.');
  return L;
}

/** 칸 머리의 얇은 보기 — gungtong.칸(일간,월지)과 같은 객체({용, 으뜸, 보좌, 기, 요지, 조문요지, 원문}) */
const 칸 = (일간, 월지) => G.칸(일간, 월지);
module.exports = { analyze, 원문보기, 원문보기안내, 걸린조문, 정렬조문, 브리프줄, 표, 칸, 여명조문, 질병조문, 표시금지유형, 비공개원문, 비공개판정, 판정어, 결말, 축찾기, 축풀이, 특수성of,
  _원시: { 透, 藏, 有, 無, 多, 一派, 支成局, 合去, 합거일간포함, 有根, 透有根, 透無根, 上半月, 下半月 }, _ctx: ctx만들기 };